/// Skewer. Cost X. Deal `base_damage` X times where X is the energy
/// spent on play. Mirrors C# `Skewer.cs` `WithHitCount(ResolveEnergyXValue())`.
/// Bead `sts2-rs-eiqfp`: read `card.energy_spent` (engine stamps this
/// before dispatch, then drains `state.player.energy` to 0) instead of
/// `state.player.energy` directly — the prior body read 0 in real play
/// because the engine had already drained energy by handler-entry. Tests
/// using `dispatch(...)` bypass the engine drain, so unit tests masked
/// the bug; the new test `eiqfp_skewer_hits_equals_energy_spent` stamps
/// `energy_spent` to match the engine.
pub(crate) fn play_skewer(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Skewer: Enemy-targeted");
    let hits = current_card_energy_spent(state);
    let base = current_card_damage(state);
    for _ in 0..hits {
        let _ = deal_damage_player_to_enemy(state, t, base);
    }
    EffectResult::Resolved
}

